let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const json = { "content-type": "application/json" };
const { fromId, toId, amount, transferId, idempotencyKey } = input;
const fromVersion = input.fromVersion;
const toVersion = input.toVersion;

function out(status, body, accounts, committed, messages, ordering, failures, retryability, extra = {}) {
  console.log(JSON.stringify({
    http: { status, headers: json, body },
    database: { accounts, transaction: { committed }, ...extra },
    messages,
    ordering,
    failures,
    retryability
  }));
}

const unchanged = [
  { id: fromId, balance: input.fromBalance, version: fromVersion },
  { id: toId, balance: input.toBalance, version: toVersion }
];

const prior = input.existingTransfer ?? input.priorTransfer ?? (input.replay === true ? input.previousResult : undefined);
const isReplay = input.replay === true || input.idempotentReplay === true || prior !== undefined;

if (isReplay) {
  const body = prior && typeof prior === "object" ? prior : {
    transferId, fromBalance: input.fromBalance, toBalance: input.toBalance, fromVersion, toVersion
  };
  out(200, body, unchanged, false, [], ["idempotency-lookup"], [], false, { idempotentReplay: true });
} else if (
  (input.currentFromVersion !== undefined && input.currentFromVersion !== fromVersion) ||
  (input.currentToVersion !== undefined && input.currentToVersion !== toVersion)
) {
  out(409, { error: "version_conflict", transferId }, unchanged, false, [], ["version-check", "rollback"],
    [{ code: "VERSION_CONFLICT", status: 409, retryable: true }], true);
} else if (!Number.isFinite(amount) || amount <= 0 || input.fromBalance < amount) {
  const insufficient = Number.isFinite(amount) && amount > 0;
  out(insufficient ? 422 : 400,
    { error: insufficient ? "insufficient_funds" : "invalid_amount", transferId },
    unchanged, false, [], ["validate", "rollback"],
    [{ code: insufficient ? "INSUFFICIENT_FUNDS" : "INVALID_AMOUNT", status: insufficient ? 422 : 400, retryable: false }], false);
} else {
  const fromBalance = input.fromBalance - amount;
  const toBalance = input.toBalance + amount;
  const newFromVersion = fromVersion + 1;
  const newToVersion = toVersion + 1;
  out(201,
    { transferId, fromBalance, toBalance, fromVersion: newFromVersion, toVersion: newToVersion },
    [{ id: fromId, balance: fromBalance, version: newFromVersion }, { id: toId, balance: toBalance, version: newToVersion }],
    true,
    [{ type: "transfer.completed", transferId, idempotencyKey, fromId, toId, amount }],
    ["debit", "credit", "commit", "publish"],
    [], false);
}

