  const a = applied();
  out(201, { transferId, fromBalance: a.fromBalance, toBalance: a.toBalance, outcome: "committed" },
    a.accounts, true,
    [{ type: "ledger.transfer-completed", transferId, amount }],
    ["lock", "debit", "credit", "idempotency-write", "message", "commit"], [], false);
}
